import (
	"fmt"
	"math/rand"
	"time"

	"nqueen-zoo/pkg/board"
)

// Step represents a single step in the solving process, including narrative for educational purposes.
type Step struct {
	Board       *board.Board
	Narrative   string
	IsBacktrack bool
}

// Solver defines the interface for different N-Queens algorithms.
type Solver interface {
	Solve(n int) (*board.Board, error)
