				bestCol = c
			}
		}

		if bestCol != -1 {
			b.RemoveQueen(queenWithConflicts)
			b.AddQueen(board.Position{Row: queenWithConflicts.Row, Col: bestCol})
		}
	}

	return b, fmt.Errorf("min-conflicts failed to find solution in maxSteps")
}

func (s *MinConflictsSolver) countConflicts(q board.Position, b *board.Board) int {
	count := 0
	for _, other := range b.Queens {
		if other == q {
			continue
		}
		// Row / Col check is actually redundant if we ensure one per row/col in our logic,
		// but let's keep it for correctness with the board model.
		if other.Row == q.Row || other.Col == q.Col ||
			(other.Row-q.Row) == (other.Col-q.Col) ||
			(other.Row-q.Row) == -(other.Col-q.Col) {
