+)
+
+// Renderer handles the visual output of the N-Queens board.
+type Renderer struct {
+	UseColor bool
+}
+
+// NewRenderer creates a new renderer instance.
+func NewRenderer(useColor bool) *Renderer {
+	return &Renderer{UseColor: useColor}
+}
+
+const (
+	Reset       = "\033[0m"
+	Bold        = "\033[1m"
+	Red         = "\033[38;5;196m"
+	Green       = "\033[38;5;46m"
+	Yellow      = "\033[38;5;226m"
+	Blue        = "\033[38;5;21m"
+	Gray        = "\033[38;5;240m"
+	BrightWhite = "\033[97m"
+)
+
+// RenderBoard prints the board to the terminal with Unicode characters and optional heatmaps.
+func (r *Renderer) RenderBoard(b *board.Board, showHeatmap bool) {
+	size := b.Size
+	if size == 0 {
+		fmt.Println("Empty board.")
+		return
+	}
+
+	heatmap := [][]int{}
+	if showHeatmap {
+		heatmap = b.GetAttackHeatmap()
+	}
+
+	fmt.Println(strings.Repeat("-", size*3))
+	for row := 0; row < size; row++ {
+		var line strings.Builder
+		line.WriteString(fmt.Sprintf("%2d | ", row))
+		for col := 0; col < size; col++ {
+			// Determine symbol and color based on state
+			symbol := "·"
+			color := ""
+
+			isQueen := false
+			for _, q := range b.Queens {
+				if q.Row == row && q.Col == col {
+					isQueen = true
+					break
+				}
+			}
+
+			if isQueen {
+				symbol = "♛"
+				color = Bold + BrightWhite
+			} else if showHeatmap {
+				count := heatmap[row][col]
+				if count > 1 {
+					color = Red        // Heavy attack
+				} else if count == 1 {
+					color = Gray       // Light attack/influence
+				}
+			}
+
+			line.WriteString(fmt.Sprintf("%s%s%s ", color, symbol, Reset))
+		}
+		fmt.Println(line.String())
+	}
+	fmt.Println(strings.Repeat("-", size*3))
+	fmt.Println("   " + strings.Repeat("───", size))
+}
