// Board represents an N x N chessboard where Queens can be placed.
type Board struct {
	Size   int
	Queens []Position
}

// NewBoard initializes an empty board of size N.
func NewBoard(n int) *Board {
	return &Board{
		Size:   n,
		Queens: make([]Position, 0),
	}
}

// IsSafe checks if a queen can be placed at the given position without being under attack.
func (b *Board) IsSafe(pos Position) bool {
	if pos.Row < 0 || pos.Row >= b.Size || pos.Col < 0 || pos.Col >= b.Size {
		return false
	}

	for _, q := range b.Queens {
		// Check row
		if q.Row == pos.Row {
			return false
		}
		// Check column
		if q.Col == pos.Col {
			return false
		}
		// Check diagonals
		rowDiff := q.Row - pos.Row
		colDiff := q.Col - pos.Col
		if rowDiff == colDiff || rowDiff == -colDiff {
			return false
		}
	}
	return true
}

// AddQueen places a queen at the given position if safe, otherwise returns an error.
func (b *Board) AddQueen(pos Position) bool {
	if b.IsSafe(pos) {
		b.Queens = append(b.Queens, pos)
		return true
	}
	return false
}

// RemoveQueen removes a queen if it exists at the given position.
func (b *Board) RemoveQueen(pos Position) {
	for i, q := range b.Queens {
		if q == pos {
			b.Queens = append(b.Queens[:i], b.Queens[i+1:]...)
			return
		}
	}
}

// GetAttackHeatmap generates a 2D grid where each cell contains the number of attack lines passing through it.
// This is used for visual rendering of "influence".
func (b *Board) GetAttackHeatmap() [][]int {
	heatmap := make([][]int, b.Size)
	for i := range heatmap {
		heatmap[i] = make([]int, b.Size)
	}

	for _, q := range b.Queens {
		// We mark every cell attacked by this queen.
		// For the purpose of "influence", a cell is attacked if it's in the same row, col, or diagonal.
		for r := 0; r < b.Size; r++ {
			for c := 0; c < b.Size; c++ {
				if r == q.Row || c == q.Col || (r-q.Row) == (c-q.Col) || (r-q.Row) == -(c-q.Col) {
					// If it's the actual queen position, maybe handle differently? 
					// We'll just count attacks for now.
					heatmap[r][c]++
				}
			}
		}
	}

	return heatmap
}

func (b *Board) String() string {
	grid := make([][]string, b.Size)
	for r := 0; r < b.Size; r++ {
		grid[r] = make([]string, b.Size)
		for c := 0; c < b.Size; c++ {
			grid[r][c] = "."
		}
	}

	for _, q := range b.Queens {
		grid[q.Row][q.Col] = "Q"
	}

	res := ""
	for r := 0; r < b.Size; r++ {
		for c := 0; c < b.Size; c++ {
			res += grid[r][c] + " "
		}
		res += "\n"
	}
	return res
}
