// Solve finds a single solution using the standard recursive approach.
func (s *BacktrackingSolver) Solve(n int) (*board.Board, error) {
	b := board.NewBoard(n)
	if s.backtrack_recursive(b, 0, n) {
		return b, nil
	}
	return nil, fmt.Errorf("no solution found")
}

func (s *BacktrackingSolver) backtrack_recursive(b *board.Board, row int, n int) bool {
	if row == n {
		return true
	}

	for col := 0; col < n; col++ {
		pos := board.Position{Row: row, Col: col}
		if b.IsSafe(pos) {
			b.AddQueen(pos)
			if s.backtrack_recursive(b, row+1, n) {
				return true
			}
			b.RemoveQueen(pos)
		}
	}
	return false
}

// GetSteps generates a channel of steps for educational playback.
func (s *BacktrackingSolver) GetSteps(n int) <-chan Step {
	ch := make(chan Step)
	go func() {
		defer close(ch)
		b := board.NewBoard(n)

		var backtrack func(int) bool
		backtrack = func(row int) bool {
			if row == n {
				ch <- Step{
					Board:       b,
					Narrative:   "🎉 Queen placement complete! We've found a valid configuration.",
					IsBacktrack: false,
				}
				return true
			}

			for col := 0; col < n; col++ {
				pos := board.Position{Row: row, Col: col}
				if b.IsSafe(pos) {
					b.AddQueen(pos)
					narrative := fmt.Sprintf("Trying to place a queen at Row %d, Column %d...", row, col)
					ch <- Step{Board: b, Narrative: narrative, IsBacktrack: false}

					if backtrack(row + 1) {
						return true
					}

					b.RemoveQueen(pos)
					ch <- Step{
						Board:       b,
						Narrative:   fmt.Sprintf("Row %d led to a dead end eventually! Backtracking from Row %d...", row+1, row),
						IsBacktrack: true,
					}
				}
			}
			return false
		}

		backtrack(0)
	}()
	return ch
}

// MinConflictsSolver implements the Min-Conflicts local search heuristic for large N.
type MinConflictsSolver struct{}

// Solve finds a single solution using min-conflicts.
func (s *MinConflictsSolver) Solve(n int) (*board.Board, error) {
	b := board.NewBoard(n)
	// Initial random configuration: one queen per row
	rand.Seed(time.Now().UnixNano())
	for r := 0; r < n; r++ {
		b.ForceAddQueen(board.Position{Row: r, Col: rand.Intn(n)})
	}

	maxSteps := 100000 // Prevent infinite loop in very rare cases for small N or specific configs
	for i := 0; i < maxSteps; i++ {
		var queenWithConflicts board.Position
		conflicts := 0

		// Count conflicts and find a random conflicted queen
		// Note: This is simplified. Usually we'd randomly pick from those with > 0 conflicts.
		for _, q := range b.Queens {
			c := s.countConflicts(q, b)
			if c > 0 {
				conflicts++
				queenWithConflicts = q
			}
		}

		if conflicts == 0 {
			return b, nil
		}

		// Move queen to a column with minimum conflicts
		bestCol := -1
		minConf := n + 1

		// Sample slightly for very large N to keep it fast?
		// For fixed N=1000, we could check all columns.
		bestCols := []int{}
		for c := 0; c < n; c++ {
			count := s.count_conflicts_at(queenWithConflicts.Row, c, b)
			if count < minConf {
				minConf = count
				bestCols = []int{c}
			} else if count == minConf {
				bestCols = append(bestCols, c)
			}
		}

		if len(bestCols) > 0 {
			chosenCol := bestCols[rand.Intn(len(bestCols))]
			b.RemoveQueen(queenWithConflicts)
			b.ForceAddQueen(board.Position{Row: queenWithConflicts.Row, Col: chosenCol})
		}
	}

	return b, fmt.Errorf("min-conflicts failed to find solution in maxSteps")
}

func (s *MinConflictsSolver) countConflicts(q board.Position, b *board.Board) int {
	count := 0
	for _, other := range b.Queens {
		if other == q {
			continue
		}
		// Row / Col check is actually redundant if we ensure one per row/col in our logic,
		// but let's keep it for correctness with the board model.
		if other.Row == q.Row || other.Col == q.Col ||
			(other.Row-q.Row) == (other.Col-q.Col) ||
			(other.Row-q.Row) == -(other.Col-q.Col) {
			count++
		}
	}
	return count
}

func (s *MinConflictsSolver) count_conflicts_at(row, col int, b *board.Board) int {
	count := 0
	for _, q := range b.Queens {
		// If the queen is already at this column/row in our logic?
		// No, we assume it's being moved FROM another spot.
		if q.Row == row && q.Col == col {
			continue
		}

		if q.Row == row || q.Col == col ||
			(q.Row-row) == (q.Col-col) ||
			(q.Row-row) == -(q.Col-col) {
			count++
		}
	}
	return count
}

func (s *MinConflictsSolver) GetSteps(n int) <-chan Step {
	ch := make(chan Step)
	go func() {
		defer close(ch)
		// Min-conflicts is not naturally "step-by-step" in a way that's
		// easily explained to students without many intermediate states.
		// We will report significant progress or just start/end.
		b := board.NewBoard(n)
		rand.Seed(time.Now().UnixNano())
		for r := 0; r < n; r++ {
			b.ForceAddQueen(board.Position{Row: r, Col: rand.Intn(n)})
		}

		ch <- Step{Board: b, Narrative: "Initial random configuration set.", IsBacktrack: false}

		maxSteps := 100000
		for i := 0; i < maxSteps; i++ {
			var queenWithConflicts board.Position
			conflicts := 0

			for _, q := range b.Queens {
				c := s.countConflicts(q, b)
				if c > 0 {
					conflicts++
					queenWithConflicts = q
				}
			}

			if conflicts == 0 {
				ch <- Step{Board: b, Narrative: "Success! Local search converged.", IsBacktrack: false}
				return
			}

			bestCol := -1
			minConf := n + 1
			for c := 0; c < n; c++ {
				count := s.count_conflicts_at(queenWithConflicts.Row, c, b)
				if count < minConf {
					minConf = count
					bestCol = c
				}
			}

			if bestCol != -1 {
				b.RemoveQueen(queenWithConflicts)
				b.ForceAddQueen(board.Position{Row: queenWithConflicts.Row, Col: bestCol})
			}

			if i%500 == 0 && i > 0 {
				ch <- Step{Board: b, Narrative: fmt.Sprintf("Iterating... Conflicts remaining: %d", conflicts), IsBacktrack: false}
			}
		}

		ch <- Step{Board: b, Narrative: "Failed to converge in time.", IsBacktrack: true}
	}()
	return ch
}
