// Solve finds a single solution using the standard recursive approach.
func (s *BacktrackingSolver) Solve(n int) (*board.Board, error) {
	b := board.NewBoard(n)
	if s.backtrack_recursive(b, 0, n) {
		return b, nil
	}
	return nil, fmt.Errorf("no solution found")
}

func (s *BacktrackingSolver) backtrack_recursive(b *board.Board, row int, n int) bool {
	if row == n {
		return true
	}

	for col := 0; col < n; col++ {
		pos := board.Position{Row: row, Col: col}
		if b.IsSafe(pos) {
			b.AddQueen(pos)
			if s.backtrack_recursive(b, row+1, n) {
				return true
			}
			b.RemoveQueen(pos)
		}
	}
	return false
}

// GetSteps generates a channel of steps for educational playback.
