+package solver_test
+
+import (
+	"testing"
+	"nqueen-zoo/pkg/solver"
+)
+
+func TestBacktrackingSolver_Solve(t *testing.T) {
+	s := &solver.BacktrackingSolver{}
+
+	tests := []struct {
+		n          int
+		shouldPass bool
+	}{
+		{n: 1, shouldPass: true},
+		{n: 2, shouldPass: false},
+		{n: 3, shouldPass: false},
+		{n: 4, shouldPass: true},
+		{n: 8, shouldPass: true},
+	}
+
+	for _, tt := range tests {
+		t.Run(string(rune(tt.n)), func(t *testing.T) {
+			b, err := s.Solve(tt.n)
+			if tt.shouldPass {
+				if err != nil {
+					t.Fatalf("Expected solution for N=%d, but got error: %v", tt.n, err)
+				}
+				if len(b.Queens) != tt.n {
+					t.Fatalf("Expected %d queens, got %d", tt.n, len(b.Queens))
+				}
+			} else {
+				if err == nil {
+					t.Fatalf("Expected no solution for N=%d, but got one", tt.n)
+				}
+			}
+		})
+	}
+}
+
+func TestBacktrackingSolver_GetSteps(t *testing.T) {
+	s := &solver.BacktrackingSolver{}
+	stepsCh := s.GetSteps(4)
+
+	count := 0
+	for step := range stepsCh {
+		count++
+		if step.Board == nil {
+			t.Errorf("Step missing board state")
+		}
+	}
+
+	if count == 0 {
+		t.Errorf("Expected steps to be emitted for N=4, got 0")
+	}
+}
